	    IdentityDocument entity = unAssignKycProfile( event.getIdentityDocumentId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindIdentityDocument( entity );
	
		// ------------------------------------------
