    @SuppressWarnings("unused")
    @QueryHandler
    public IdentityDocument handle( FindIdentityDocumentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getIdentityDocumentId() );
    }
    
    /**
     * Method to retrieve a collection of all IdentityDocuments
     *
     * @param	query	FindAllIdentityDocumentQuery 
     * @return 	List<IdentityDocument> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<IdentityDocument> handle( FindAllIdentityDocumentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindIdentityDocument,
 * but only if the id matches
 *
 * @param		entity	IdentityDocument
 */
	protected void emitFindIdentityDocument( IdentityDocument entity ) {
		LOGGER.info("handling emitFindIdentityDocument" );
		
	    queryUpdateEmitter.emit(FindIdentityDocumentQuery.class,
	                            query -> query.getFilter().getIdentityDocumentId().equals(entity.getIdentityDocumentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllIdentityDocument
	 * 
	 * @param		entity	IdentityDocument
	 */
	protected void emitFindAllIdentityDocument( IdentityDocument entity ) {
		LOGGER.info("handling emitFindAllIdentityDocument" );
		
	    queryUpdateEmitter.emit(FindAllIdentityDocumentQuery.class,
	                            query -> true,
	                            entity);
	}

